  "CLI 由当前中央部署准备，账号凭据由厂商 CLI 管理。": "CLI подготавливается этим центральным развёртыванием. Учётные данные аккаунта управляются CLI производителя.",
  "授权并连接账号": "Авторизовать и подключить аккаунт",
