  "应用凭据仅发往当前中央，并通过标准输入交给厂商 CLI。": "Учётные данные приложения отправляются только на этот центральный узел и передаются CLI производителя через стандартный ввод.",
  "确认钉钉组织启用 CLI，并核对账号和读取权限。": "В вашей организации DingTalk должен быть включён доступ по CLI. Проверьте аккаунт, организацию и разрешения на чтение на странице авторизации.",
