  "授权完成后，确认历史范围并启用同步。": "После авторизации подтвердите диапазон истории и включите синхронизацию.",
  "网页或客户端与中央的协议版本不匹配。": "Версии протокола страницы или клиента и центрального узла несовместимы. Используйте совместимые версии.",
  "请求的资源不存在或已删除。": "Запрошенный ресурс не существует или был удалён.",
  "所需服务暂不可用。": "Нужная служба временно недоступна. Проверьте состояние центрального узла и повторите попытку.",
  "中央未接受当前登录身份（401）。登录信息可能已失效。": "Центральный узел не принял текущие данные для входа (401). Проверьте их и повторите попытку.",
  "请求内容超过中央或公网入口的大小限制（413）。": "Запрос превышает ограничение размера центрального узла или публичного шлюза (413). Отправьте меньше данных и повторите попытку.",
