  "发布信息与当前组件不匹配，已停止更新。": "Информация о выпуске не соответствует текущему компоненту. Обновление остановлено.",
  "更新检查未完成，检查网络和发布服务后重试。": "Проверка обновлений не завершена. Проверьте сеть и службу выпусков, затем повторите попытку.",
  "外部处理结果待确认。先查看任务回执。": "Результат предыдущей внешней обработки не подтверждён. Проверьте квитанцию задачи, прежде чем решить, стоит ли повторить.",
  "文件仍在处理中，等待当前任务结束后再操作。": "Файл всё ещё обрабатывается. Дождитесь завершения текущей задачи.",
  "此文件当前采用仅归档策略，未安排内容处理。": "Для этого файла действует политика «только архив». Обработка содержимого не запланирована.",
