  "不读取或上传正文，也不会转写。": "Содержимое не читается и не загружается, аудио не транскрибируется.",
  "中央说明（版本 {0}）：\n{1}\n\n本机说明：\n{2}": "Описание центрального узла (версия {0}):\n{1}\n\nЛокальное описание:\n{2}",
  "仅保留提取内容": "Сохранять только извлечённое содержимое",
