  "已跳过": "Пропущено",
  "这是 AppleDouble 文件系统元数据，原件已保留，已跳过内容处理。": "Это метаданные файловой системы AppleDouble. Оригинал сохранён; обработка содержимого пропущена.",
  "归档内容不存在或已按保留策略清理；同步凭据仍可查看。": "Архивное содержимое отсутствует или удалено по политике хранения; квитанция синхронизации остаётся доступной.",
  "本机副本已变化；尚无可读取的中央接收凭据。": "Локальная копия изменилась; читаемая квитанция приёма центрального узла пока недоступна.",
