  "接收回执与中央识别、索引和整理分别进行。失败重试保留原回执，内容按当前归档策略读取。": "Квитанции приёма не связаны с распознаванием, индексацией и обработкой на центральном узле. При повторах сохраняются исходные квитанции; содержимое читается по текущей политике хранения архива.",
  "选择一条记录查看内容。": "Выберите запись для просмотра содержимого.",
