  "内容": "Содержимое",
  "此记录仅同步目录信息，未上传正文或原件。": "Эта запись синхронизирует только метаданные каталога; содержимое или оригинал не загружались.",
  "内容已接收，中央仍在处理正文。稍后刷新。": "Содержимое получено; центральный узел всё ещё обрабатывает его. Обновите позже.",
  "此记录暂无可预览正文；可查看元数据或在中央打开原件。": "Предпросмотр содержимого пока недоступен. Проверьте метаданные или откройте оригинал на центральном узле.",
  "下一页正文": "Следующая страница содержимого",
  "元数据": "Метаданные",
  "刷新内容": "Обновить содержимое",
  "已上传内容来自中央归档。本机副本可能已清理。正文预览最多 100000 字符，原件和完整内容可在中央查看。": "Загруженное содержимое читается с центрального узла; локальная копия могла быть очищена. В предпросмотре отображается до 100 000 символов. Оригиналы и полное содержимое доступны на центральном узле.",
