  "JSON 整体替换。系统管理必需字段，已有值不回显。": "Введите JSON-объект по текущему протоколу; заменяется целиком. Сообщения, инструменты и обязательные поля управляются Mote; существующие значения скрыты.",
  "允许在更改后的服务地址复用已保存的凭据": "Разрешить сохранённые учётные данные по изменённому адресу сервиса",
  "保留的 API key、请求头或高级参数会发往当前地址。也可填写新值或清除旧值。": "Сохранённые API-ключи, заголовки или дополнительные параметры будут отправлены по введённому адресу. Можно также ввести новые значения или очистить старые.",
  "中央发送少量合成内容，最长等待 30 秒，可能产生费用。测试不读资料库、不保存草稿。": "При проверке центральный узел отправляет небольшой синтетический запрос, ждёт до 30 секунд, возможны небольшие расходы; архив не читается. Проверка не сохраняет черновик.",
