  "此 MVP 只支持 macOS 采集；Windows/Linux 需要接入可靠前台应用识别后才可启用": "Этот MVP поддерживает сбор только на macOS. Windows/Linux требуют надёжного определения активного приложения.",
  "已开启；按应用级别记录，完整内容先经过本地隐私过滤": "Включено; используются уровни сбора по приложениям, полное содержимое проходит локальную фильтрацию конфиденциальности",
  "采集已停止；本地记录保留，同步按设置独立运行": "Сбор остановлен. Локальные записи сохранены; синхронизация работает отдельно по настройкам.",
  "锁屏或休眠中，暂停采集": "Экран заблокирован или система спит; сбор приостановлен",
  "已达到空闲阈值，暂停采集；操作电脑后恢复": "Достигнут порог бездействия; сбор возобновится, когда вы начнёте пользоваться компьютером",
  "无法确认电量，按你启用的电量策略暂停": "Состояние батареи неизвестно; приостановлено согласно вашей политике питания",
  "已达到你设置的电量暂停条件": "Достигнуто заданное вами условие паузы по заряду батареи",
  "当前应用设置为不记录，已跳过本次采样": "Текущее приложение исключено; сэмпл пропущен",
  "仅记录应用活动；未采集屏幕、窗口标题或正文": "Только активность приложений; экран, заголовки окон и текст не собираются",
  "录屏未授权，仅应用活动可采。打开系统权限设置。": "Для полного содержимого требуется разрешение на запись экрана. Выборка только активности остаётся доступной. Откройте системные настройки разрешений.",
  "无法获取主屏截图，本次采集已跳过": "Не удалось получить снимок основного экрана; сэмпл пропущен",
