  "采集失败，已跳过本次记录": "Захват не удался; запись пропущена",
  "待传队列属于原中央。恢复原连接。": "Локальная очередь привязана к исходному узлу. Восстановите подтверждённое подключение.",
  "中央已删除此记录，不会重新创建；本机副本保留待处理。": "Центральная запись удалена и не будет создана заново. Локальная копия сохранена для проверки.",
  "上传失败，队列已保留": "Загрузка не удалась; очередь сохранена",
  "同步失败，本地记录已保留": "Синхронизация не удалась; локальные записи сохранены",
  "质量范围 40–95，最长边范围 640–2560": "Качество должно быть 40–95; максимальная сторона 640–2560",
  "{0} 必须为 {1}–{2} 之间的整数": "{0} должно быть целым числом от {1} до {2}",
  "遮挡区域必须为数组，最多 100 个": "Области маскировки должны быть массивом не более чем из 100 элементов",
  "遮挡区域格式不正确": "Недопустимый формат области маскировки",
  "遮挡区域使用 0–1 相对坐标，且不得超出画面": "Области маскировки используют относительные координаты от 0 до 1 и не должны выходить за пределы изображения",
  "中央地址不正确": "Недопустимый URL центрального узла",
  "中央需要完整的 http:// 或 https:// 地址": "Центральному узлу нужен полный URL вида http:// или https://",
