  "空闲暂停秒数": "Секунды бездействия до паузы",
  "诊断采样秒数": "Секунды диагностической выборки",
  "JPEG 质量": "Качество JPEG",
  "截图最大边长": "Максимальная сторона снимка экрана",
  "低电量暂停百分比": "Процент заряда для паузы при низком уровне",
  "待传记录未处理。上传或备份后更换中央或令牌。": "Ожидающие записи не позволяют сменить узел или токен. Сначала загрузите их или сделайте резервную копию и обработайте старую очередь.",
  "待传记录未处理。上传，或导出并移走队列后重启。": "Ожидающие записи не позволяют сменить узел. Загрузите их либо экспортируйте и переместите старую очередь перед перезапуском.",
  "切换中央必须明确输入新节点令牌，不能复用已有令牌": "Для смены узла нужно явно ввести новый токен; существующие токены нельзя использовать повторно",
  "远程部署至少需要 32 字符访问令牌": "Удалённое развёртывание требует токен доступа не короче 32 символов",
  "设备标识无效": "Недопустимый ID устройства",
  "系统密钥存储不可用，无法解密令牌": "Системное хранилище ключей недоступно; не удаётся расшифровать токен",
  "配置不可读。检查系统凭据，或备份后修复。": "Не удаётся прочитать конфигурацию. Проверьте системное хранилище ключей или сделайте резервную копию и восстановите файл конфигурации.",
  "系统加密存储不可用，拒绝保存明文令牌": "Системное зашифрованное хранилище недоступно; токен в открытом виде не сохраняется",
  "本地记录的节点绑定信息无效": "Недопустимая привязка узла для локальных записей",
  "待传记录只归原节点和凭据。恢复原连接。": "Ожидающие записи привязаны к исходному узлу или учётным данным. Восстановите это подключение для синхронизации; перепривязка заблокирована.",
  "中央确认格式无效，原连接保持不变": "Недопустимое центральное подтверждение; исходное подключение не изменено",
  "设备已登记或邀请已使用。在中央为此设备生成邀请。": "Устройство уже зарегистрировано или приглашение использовано. Выберите это устройство в центральном узле и создайте новое приглашение.",
  "中央连接失败或超时。核对中央地址、HTTPS 证书和网络。重定向会被拒绝。": "Подключение не удалось или истёк тайм-аут. Проверьте URL узла, сертификат HTTPS и сеть. Перенаправления отклоняются.",
  "导入连接邀请，或保存访问令牌。": "Сначала импортируйте приглашение или сохраните токен доступа",
  "导入连接邀请文字": "Импортируйте текст приглашения",
  "先预览邀请，再核对中央地址。": "Сначала просмотрите приглашение и подтвердите отображаемый URL узла",
  "待传截图、记录或来源版本未处理。上传或备份后更换。": "Ожидающие снимки, быстрые заметки или версии источников не позволяют сменить узел или учётные данные. Загрузите их или сделайте резервную копию и обработайте старую очередь.",
  "采集或同步尚未结束。稍后重试连接。": "Сбор, загрузка или синхронизация источников ещё выполняются. Повторите позже.",
