  "邀请无效，原连接保留。核对格式、有效期和大小。": "Не удаётся прочитать действительное приглашение. Проверьте формат JSON/QR, срок действия и размер файла. Исходное подключение не изменено.",
  "系统加密存储不可用，不能交换并保存凭据": "Системное зашифрованное хранилище недоступно; не удаётся обменять и сохранить учётные данные",
  "中央身份不匹配，原连接保留。重新生成邀请。": "Несоответствие подтверждения идентичности центральных учётных данных. Исходное подключение не изменено; создайте новое приглашение.",
