  "UTF-8 文本资料": "Текстовые материалы UTF-8",
  "导出本机数值诊断（不含内容与令牌）": "Экспортировать локальную числовую диагностику (без содержимого и токенов)",
  "导出支持包（数值与固定事件，不含内容和令牌）": "Экспортировать пакет поддержки (метрики и фиксированные события; без содержимого и токенов)",
  "选择本机截图保存位置": "Выберите локальное место хранения снимков",
  "选择位置": "Выбрать расположение",
  "无法打开截图目录，检查磁盘是否已连接": "Не удаётся открыть каталог снимков. Проверьте, подключён ли диск.",
  "命名环境通过带 --profile 的命令启动。": "Для именованных сред запускайте с --profile. Системные объекты входа по умолчанию не сохраняют аргументы среды.",
  "通过本机文件夹选择器选择截图位置，再保存设置": "Выберите место хранения снимков через локальный выбор папок, затем сохраните",
  "先保存截图位置，再保存中央连接。": "Сначала сохраните место хранения снимков, затем отдельно подключение узла. Каждое переключение применяется автоматически.",
  "导出已脱敏待上传队列（包含个人资料）": "Экспортировать ожидающую очередь с маскировкой (содержит личные данные)",
