  "正文最多 20000 个字符位，部分表情占多个字符位；原草稿未改动": "Ограничение текста — 20000 кодовых единиц; некоторые эмодзи занимают несколько. Исходный черновик не изменён.",
  "心情最多 80 个字符位，部分表情占多个字符位；原草稿未改动": "Ограничение настроения — 80 кодовых единиц; некоторые эмодзи занимают несколько. Исходный черновик не изменён.",
  "记录草稿无法读取。先备份草稿文件再修复": "Не удаётся прочитать черновик заметки. Сделайте резервную копию файла черновика перед восстановлением.",
  "草稿已更新，重新载入当前草稿": "Черновик обновлён. Перезагрузите текущий черновик.",
  "草稿有待完成的保存。先重试保存。": "У этого черновика есть незавершённое сохранение. Сначала повторите сохранение; подготовленные записи нельзя изменить.",
  "草稿已更新，此提交不会重复创建记录": "Черновик обновлён; эта отправка не создаст дубликат",
  "填写记录正文，不能只有空白": "Введите текст заметки; только пробельные символы недопустимы",
  "心情不能只有空白；清空心情后也可以保存": "Настроение не может состоять только из пробелов. Очистите его, чтобы сохранить без настроения.",
  "提交版本已过期，重新保存当前草稿": "Версия отправки устарела. Сохраните текущий черновик заново.",
  "待完成记录属于原中央；恢复原节点后完成保存": "Ожидающая запись принадлежит исходному узлу. Восстановите его, чтобы завершить сохранение.",
  "待完成记录不能改写，重新载入草稿后重试": "Ожидающую запись нельзя изменить. Перезагрузите черновик и повторите.",
  "为 --profile 指定环境短名": "Укажите короткое имя среды после --profile",
  "只允许指定一个 profile": "Можно указать только один профиль",
  "Profile 需为 1–32 个小写字母、数字、下划线或连字符": "Профиль должен содержать 1–32 строчные буквы, цифры, подчёркивания или дефисы",
  "开发或测试环境需指定独立中央。": "Среды разработки/тестирования не могут автоматически использовать повседневный узел 47832. Используйте отдельный узел или явно настройте его в приложении.",
  "存储切换待恢复，新旧副本保留。重新打开 Mote。": "Переключение хранилища требует восстановления. Обе копии сохранены; выйдите и откройте Mote заново.",
  "存储目录含符号链接，不能安全迁移；原目录保持有效": "Хранилище содержит символические ссылки и не может быть безопасно перенесено. Исходный каталог остаётся активным.",
  "存储目录含特殊文件，不能安全迁移": "Хранилище содержит специальные файлы и не может быть безопасно перенесено",
  "迁移文件校验失败，原目录保持有效": "Проверка переноса не удалась; исходный каталог остаётся активным",
  "截图目录不能是符号链接或其他文件。重新选择": "Каталог снимков не может быть символической ссылкой или другим файлом. Выберите заново.",
  "存储目录归属标记无效": "Недопустимый маркер принадлежности хранилища",
  "截图目录不可用。连接原磁盘，已有记录保留。": "Каталог снимков недоступен. Подключите исходный диск и повторите; записи не будут заменены пустым каталогом.",
  "目录与当前环境或设备不匹配。": "Хранилище принадлежит другой среде или устройству. Очереди нельзя использовать совместно.",
  "截图目录不可用。连接原磁盘。不会切换存储或创建空队列。": "Выбранный каталог снимков недоступен. Подключите исходный диск и повторите. Пустая очередь или резервная копия созданы не будут.",
  "迁移原目录不可用。连接原磁盘。不会创建空队列。": "Исходный каталог, необходимый для восстановления, недоступен. Подключите исходный диск; пустая очередь создана не будет.",
  "节点绑定不完整，副本保留。检查原磁盘。": "Привязка узла хранилища неполная. Копии переноса сохранены; проверьте исходный диск.",
  "选择应用数据目录以外的文件夹。": "Выберите папку вне данных приложения Mote, чтобы не смешивать среды или файлы приложения",
  "该位置已有 Mote 存储。选择其他文件夹。": "В выбранном месте уже есть хранилище Mote. Выберите другую папку, чтобы не перезаписать записи.",
  "新旧存储目录不能相同或互相嵌套": "Старый и новый каталоги хранилища не могут совпадать или быть вложенными",
  "旧副本归属无法确认，已保留待处理": "Принадлежность старой копии не подтверждена; сохранена для проверки",
  "迁移恢复记录无效": "Недопустимая запись восстановления переноса",
  "迁移记录与当前环境不匹配，保留目录并检查配置": "Запись переноса не соответствует этой среде. Сохраните каталог и проверьте конфигурацию.",
  "旧迁移副本待清理。连接旧磁盘后重试。": "Предыдущая копия переноса ожидает очистки. Убедитесь, что старый диск доступен, затем повторите.",
  "目标位置与应用环境目录冲突": "Целевое расположение конфликтует с каталогом среды приложения",
  "新位置已存在文件，迁移不会覆盖或合并已有记录": "Целевое расположение уже содержит файлы. Перенос не перезапишет и не объединит записи.",
  "新位置空间不足。释放空间或选择其他位置": "Недостаточно места в целевом расположении. Освободите место или выберите другое расположение.",
