  "来源目录不可用。保留本机清单，暂停判断删除。": "Корень источника недоступен или изменился. Локальный каталог сохранён; удаление не выводится (деградация).",
  "部分会话无法读取或超限。进度保留。": "Некоторые сессии нечитаемы или событие превышает ограничения. Прогресс сохранён для повтора.",
  "已保存当前批次。下次扫描继续。": "Текущая партия сохранена. Остальные сессии и незавершённые конечные строки продолжатся при следующих сканированиях.",
  "同步已取消，待传版本已保留": "Синхронизация отменена; ожидающие версии сохранены",
  "同步未完成，待传版本保留。核对来源和网络。": "Синхронизация не завершена. Проверьте разрешения, сеть или пути источников. Ожидающие версии сохранены.",
