  "中央来源已暂停，在中央来源页恢复": "Источник приостановлен центральным узлом. Возобновите его на центральной странице «Источники».",
  "中央同步失败，已保留本地版本，稍后重试": "Центральная синхронизация не удалась. Локальные версии сохранены; повторите позже.",
