  "同一中央重新授权后，待传截图、记录和来源版本继续发往此地址。以地址和 HTTPS 证书核对中央身份。确认它仍由你控制。": "После повторной авторизации того же узла ожидающие снимки, заметки и версии источников продолжат отправляться на этот адрес. Идентичность узла определяется этим URL и сертификатом HTTPS; убедитесь, что вы по-прежнему контролируете его.",
  "更换中央时须无待传截图、记录和来源版本。保留设备 ID、隐私设置和本地模型。": "Для смены узла не должно быть ожидающих снимков, заметок или версий источников. ID устройства, настройки конфиденциальности и локальные модели сохраняются.",
