  "预设": "Пресет",
  "自定义…": "Свой вариант…",
  "找到 {0} 个应用，列表只在本机设置中使用。": "Найдено приложений: {0}. Выберите одно, чтобы настроить уровень сбора. Список используется только для локальных настроек.",
  "暂未找到应用，可在下方“手动输入 ID”中添加。": "Приложения не найдены. Добавьте через «Ввести ID вручную» ниже.",
  "{0} 已加入完全排除列表，保存设置后生效。": "{0} добавлено в полные исключения. Сохраните настройки, чтобы применить.",
  "最多 100 个遮挡区域，需要位于屏幕以内，宽高大于 0。检查高级 JSON。": "До 100 масок в пределах экрана, с шириной и высотой больше 0. Проверьте расширенный JSON.",
  "尚未设置固定遮挡。选择上方预设即可添加。": "Фиксированных масок пока нет. Выберите пресет выше, чтобы добавить.",
  "区域 {0}": "Область {0}",
  "移除遮挡区域 {0}": "Удалить маску {0}",
