  "部分词级时间与相邻片段重叠，已保留整句并标记说话人不确定；原始转写未改动。": "Временные метки некоторых слов перекрываются с соседними сегментами. Предложения сохранены целиком с неопределённой принадлежностью говорящему; исходный транскрипт не изменён.",
