  "填开放平台密钥，选择支持工具调用的模型。": "Используйте ключ API открытой платформы и модель с поддержкой инструментов. Параметры рассуждений настройте по документации модели.",
  "月之暗面 / Kimi": "Moonshot / Kimi",
  "使用 Kimi API key，思考方式沿用模型默认。": "Используйте ключ API Kimi. Параметры рассуждений различаются у поколений моделей; по умолчанию — автоматический режим.",
  "使用 MiniMax API key。也可切换 Messages 协议并将地址改为 https://api.minimax.cn/anthropic。": "Используйте ключ API MiniMax. Для Messages измените URL на https://api.minimax.cn/anthropic.",
  "百度智能云 / 千帆": "Baidu Cloud / Qianfan",
  "使用新版 API Key（Bearer）；不要填写旧版 OAuth access_token。模型须支持工具调用。": "Используйте новый ключ API (Bearer), а не старый access_token OAuth. Модель должна поддерживать инструменты.",
  "腾讯云 / TokenHub": "Tencent Cloud / TokenHub",
  "迁移至 TokenHub 时，同时更换地址和密钥。": "Новый сервис моделей Tencent использует новый ключ TokenHub. При миграции со старой платформы Hunyuan меняются и URL, и ключ.",
