  "已有混元凭据仅用于旧连接。新连接选 TokenHub。": "Для существующих аккаунтов Hunyuan. Для новых подключений рекомендуется TokenHub; ключи двух платформ несовместимы.",
  "硅基流动 / SiliconFlow": "SiliconFlow",
  "填写完整模型 ID；工具调用与思考能力取决于所选模型。": "Введите полный ID модели. Поддержка инструментов и рассуждений зависит от выбранной модели.",
  "讯飞 / 星火": "iFlytek / Spark",
  "填写 HTTP APIPassword，按版本核对地址和模型 ID。": "Используйте APIPassword HTTP-сервиса. Предустановлен URL X2; для других версий измените URL и ID модели по консоли.",
  "阶跃星辰 / StepFun": "StepFun",
  "使用开放平台 API key；Step Plan 套餐需改为 https://api.stepfun.com/step_plan/v1 并选择套餐可用模型。": "Используйте ключ API открытой платформы. Для Step Plan укажите https://api.stepfun.com/step_plan/v1 и модель, доступную в вашем тарифе.",
  "默认使用 Responses；也可切换 Chat Completions。填写账户可用的模型 ID。": "По умолчанию Responses; также поддерживается Chat Completions. Укажите ID модели, доступной вашему аккаунту.",
