  "Gemini API key。模型须支持工具调用，保留思考签名。": "Нативный API Google с ключом Gemini, сохраняет подписи мыслей при вызовах инструментов. Выберите модель с поддержкой инструментов.",
  "填 Azure 资源地址和部署名称，密钥经 api-key 请求头发送。": "Введите URL ресурса Azure https://resource.openai.azure.com/openai/v1 и имя развёртывания как модель. Ключ передаётся в заголовке api-key.",
