  "全部截图": "Все скриншоты",
  "返回采集时段": "Назад к сессиям захвата",
  "记录详情": "Детали записи",
  "关闭详情": "Закрыть детали",
  "连接系统日历": "Подключить системный календарь",
  "连接 Coding Agent": "Подключить агент кодирования",
  "采集所选 Agent": "Собирать данные выбранных агентов",
