  "精确路径或目录前缀，适用于文件和编码对话来源。": "Точные пути или префиксы каталогов для источников файлов и диалогов кодирования.",
  "上传前遮盖的确切文字（每行一项，可选）": "Точный текст для маскировки перед загрузкой (необязательно; по одному на строку)",
  "跟踪删除": "Отслеживать удаления",
  "仅完整扫描后标记缺失。中央历史保留，默认关闭。": "Только полное успешное сканирование отмечает исчезнувшие элементы в области; история на центральном узле сохраняется. По умолчанию выключено.",
  "来源权限与保存方式": "Разрешения источников и режим хранения",
  "仅在连接日历时申请只读权限。同步所选日历中过去 30 天至未来 90 天的资料。App 驻留时持续检查变化，按上传策略同步。退出后暂停，重开后恢复。": "Читается только выбранный календарь в диапазоне от 30 дней назад до 90 дней вперёд; системные календари не изменяются. Разрешение запрашивается только при подключении календаря. Пока приложение работает, оно проверяет локальные изменения и синхронизирует по общей политике загрузки; после выхода проверки приостанавливаются до следующего запуска.",
  "每来源最多待传 4000 版本或 32 MiB。路径和待传正文只存于本机私有来源目录，支持包不含这些内容。更换中央或令牌时使用独立同步状态。旧版本只发往原中央。": "Каждый источник может поставить в очередь до 4000 версий / 32 МиБ. Пути и ожидающий текст хранятся только в приватном локальном каталоге источника и не попадают в пакеты поддержки. Смена узла или токена использует отдельное состояние синхронизации; ожидающие версии старого узла не отправляются на новый.",
  "日历权限": "Разрешение на календарь",
  "连接与设备": "Подключение и устройство",
  "中央、连接邀请与设备名称": "Центральный узел, приглашения и имя устройства",
  "上传与同步": "Загрузка и синхронизация",
