  "运行概况": "Обзор работы",
  "队列与模型状态实时更新。": "Состояние очереди и модели обновляется в реальном времени.",
  "需要处理计数、耗时和 CPU 数据时，可开启本机诊断。": "Включите локальную диагностику, чтобы видеть счётчики, время обработки и данные CPU.",
  "诊断仅记录数值与固定阶段事件，不上传个人正文。": "Диагностика записывает только числа и события фиксированных этапов; личное содержимое не загружается.",
  "采样时长估算设备活动。": "Длительность замера оценивает активность устройства между двумя замерами одного приложения и не измеряет ваше внимание.",
  "使用连接邀请": "Использовать приглашение на подключение",
  "在中央仓库的“设备连接”中生成邀请，然后粘贴或导入。": "Создайте приглашение в разделе «Подключения устройств» центрального архива, затем вставьте или импортируйте его.",
  "推荐": "Рекомендуется",
  "使用可信中央地址。预览时不发送请求。": "Используйте только доверенный центральный адрес. Предпросмотр не отправляет сетевых запросов.",
  "预览连接": "Предпросмотр подключения",
