  "放大查看": "Увеличить",
  "适应窗口": "По размеру окна",
  "两图按原尺寸联动滚动。质量与压缩率分别显示。": "Оба изображения выровнены в исходном масштабе; прокрутка любого из них синхронно показывает детали. Параметр качества — не процент уменьшения размера файла.",
  "高级设置": "Дополнительные настройки",
  "设备与手动连接": "Устройство и подключение вручную",
  "已有节点地址与访问令牌时，也可以手动配置。": "Можно также вручную указать существующие адрес узла и токен доступа.",
  "用于在中央区分记录来源。": "Идентифицирует записи этого устройства на центральном узле.",
