  "留空可仅在本机采集；远程地址使用 HTTPS。": "Оставьте пустым для захвата только локально; удалённые адреса требуют HTTPS.",
  "访问令牌": "Токен доступа",
  "使用系统密钥存储加密；不会展示已有令牌。": "Шифруется системным хранилищем учётных данных; существующие токены не показываются.",
  "将本机积存记录同步到这个节点": "Синхронизировать накопленные локальные записи с этим узлом",
  "已绑定的待传记录始终归原中央。清空地址不会解除绑定。迁移前完成上传，或导出并移走旧队列。": "Ожидающие записи, привязанные к узлу, всегда принадлежат ему. Очистка адреса не отвязывает их. Перед переносом завершите загрузку или экспортируйте и удалите старую очередь.",
  "本地采集和上传独立运行": "Локальный захват и загрузка работают независимо",
  "01 · 先保存": "01 · Сначала сохранение",
  "02 · 按策略发送": "02 · Отправка по политике",
  "停止采集后旧记录继续同步。休眠或退出后延迟。": "Остановка захвата не останавливает синхронизацию существующих записей. Расписания выполняются, пока приложение работает; сон компьютера или выход откладывают их.",
  "管理连接地址": "Управление адресом подключения",
  "仅采集主屏幕。锁屏和休眠时始终暂停。": "Захватывается только основной дисплей. При блокировке и сне захват всегда приостанавливается.",
  "采样间隔（秒）": "Интервал замеров (секунды)",
  "相同画面复用本地图像，保留每次采样记录。": "Одинаковые экраны повторно используют локальные изображения, каждая запись замера сохраняется.",
  "连续空闲后暂停（秒）": "Пауза после непрерывного простоя (секунды)",
  "默认 300；设为 0 可关闭空闲检测。": "По умолчанию 300; установите 0, чтобы отключить определение простоя.",
  "运行与电源": "Работа и питание",
  "让 Mote 按照你的设备使用方式运行。": "Настройте Mote под ваш стиль использования устройства.",
