  "顶部菜单栏": "Верхняя строка меню",
  "左侧栏": "Левая боковая панель",
  "屏幕示意 · 遮挡区域不会保存": "Схема экрана · Замаскированные области не сохраняются",
  "遮挡从主屏左上角定位，保存和识别前生效。": "Маски привязаны к левому верхнему углу основного дисплея и применяются до сохранения и распознавания текста. После добавления настройте их под реальную раскладку экрана.",
  "遮挡区域 JSON": "JSON областей масок",
  "x / y / width / height 使用 0–1 的比例。编辑后离开输入框即可更新示意。": "x / y / width / height задаются долями от 0 до 1. После редактирования покиньте поле, чтобы обновить схему.",
  "设备元数据": "Метаданные устройства",
  "选择是否附带设备运行环境。": "Выберите, прикладывать ли сведения об окружении устройства.",
  "上传设备与采样元数据": "Загружать метаданные устройства и замеров",
  "关闭后仍保留应用和时间。文件时间元数据不受影响。": "При выключении сохраняются базовые записи приложений и времени; временные метаданные файловых источников не затрагиваются.",
  "可能包含哪些数据": "Какие данные могут включаться",
  "元数据可含系统版本、硬件型号、语言时区、电量和温度级别、空闲与锁屏状态、可用空间，以及完整内容的截图参数。无数据时留空。序列号、SSID 和定位不采集。": "Может включать версию ОС, модель оборудования, язык и часовой пояс, заряд, температурный уровень, время простоя, состояние блокировки, свободное место и параметры скриншотов полного содержимого. Серийные номера, SSID и геолокация не включаются. Значения, не предоставляемые платформой, опускаются.",
  "最大生成 token": "Максимум генерируемых токенов",
  "图像与资源优化": "Оптимизация изображений и ресурсов",
  "打开图片压缩预览": "Открыть предпросмотр сжатия изображений",
  "在存储占用和文字清晰度之间调整。": "Настройте баланс между занимаемым местом и чёткостью текста.",
  "较低质量减少存储，可能影响小字识别。": "Более низкое качество уменьшает занимаемое место, но может ухудшить распознавание мелкого текста.",
  "本机诊断": "Локальная диагностика",
  "采集诊断不含截图、OCR、记录、审查策略、中央地址或令牌。电量反映整机变化，无法判断 Mote 的耗电。": "Не записывает скриншоты, OCR, быстрые заметки, политики проверки, адреса узлов и токены. Изменение заряда отражает всё устройство, а не потребление Mote.",
  "诊断采样（秒）": "Интервал диагностики (секунды)",
  "诊断未开启": "Диагностика не включена",
  "刷新数值": "Обновить показатели",
  "导出数值诊断": "Экспорт числовой диагностики",
  "导出安全支持包": "Экспорт безопасного пакета поддержки",
  "查看本地日志": "Просмотр локальных журналов",
  "设置保存后立即生效，保持当前采集开停状态。": "Сохранённые настройки действуют сразу и сохраняют текущее состояние захвата.",
  "还原修改": "Отменить изменения",
  "本地数据与迁移": "Локальные данные и миграция",
  "队列备份含脱敏截图和 OCR，无访问令牌。中央单独导出。": "Резервные копии очереди включают замаскированные скриншоты и OCR, но не токены доступа. Центральный архив экспортируйте на стороне сервера.",
