  "AI 原生个人上下文采集与中央归档": "AI-нативный сбор личного контекста и центральный архив",
  "检查新版本，保持你的本地采集器更新。": "Проверяйте новые версии, чтобы ваш локальный сборщик оставался актуальным.",
  "更新渠道": "Канал обновлений",
  "正在读取版本…": "Чтение версии…",
  "下载并校验": "Загрузить и проверить",
  "安装并重启": "Установить и перезапустить",
  "显示已验证安装包": "Показать проверенный установщик",
  "发布说明": "Примечания к выпуску",
  "更新来源与安装说明": "Источник обновлений и инструкции по установке",
  "更新来自 GitHub utopiafar/mote，只接受内置发布公钥验证通过的安装包。": "Обновления поступают с GitHub utopiafar/mote. Принимаются только установщики, проверенные встроенным открытым ключом выпуска.",
  "安装前保存设置并退出同一 App 的其他环境。更新前会先保存记录草稿。各环境的数据、Keychain、草稿、队列及模型保留。临时签名更新可能需重新授权。目录只读时可用 Finder 替换。": "Перед установкой сохраните неотправленные настройки. Черновики быстрых заметок сохраняются первыми; все профили, записи Keychain, черновики, очереди и каталоги моделей сохраняются. Сначала завершите другие профили этого приложения. После обновления с ad-hoc-подписью macOS может снова запросить разрешения; ваши данные не сбрасываются. Если каталог установки недоступен для записи, замените приложение вручную через Finder.",
  "关闭窗口后驻留。通过菜单栏退出。": "После закрытия окна Mote остаётся в строке меню; для полного выхода используйте команду выхода в строке меню.",
  "由你指定原文，不自动推断": "Исходный текст задаёте вы; он не выводится автоматически",
  "粘贴邀请 JSON 或 mote://connect?data=…": "Вставьте JSON приглашения или mote://connect?data=…",
