  "断开会停止读取并暂停这些来源，保留已归档资料。飞书端授权及 CLI 凭据仍保留，可在飞书中单独撤销。": "Отключение останавливает чтение и приостанавливает эти источники, сохраняя заархивированные материалы. Авторизация Feishu и учётные данные CLI сохраняются; доступ можно отозвать отдельно в Feishu.",
  "停止读取并暂停这些来源。保留归档、飞书授权和 CLI 凭据。可在飞书单独撤销。": "Отключение останавливает чтение и приостанавливает эти источники, сохраняя заархивированные материалы. Авторизация Feishu и учётные данные CLI сохраняются; доступ можно отозвать отдельно в Feishu.",
