  "操作超时。检查服务端网络，或重新发起授权。": "Время операции истекло. Проверьте сеть сервера или начните авторизацию заново.",
  "飞书 CLI 未完成。核对网络、权限和钥匙串访问。": "Операция Feishu CLI не завершена. Проверьте сеть, разрешения приложения и доступ сервисного аккаунта к системной связке ключей, затем повторите.",
