  "超出名额时排队。降低上限不打断在途任务。LLM 名额含一次运行和工具循环，Codex 内部请求不单独计量。": "Работа сверх квоты ставится в очередь. Снижение лимитов не прерывает выполняемую работу. Квота LLM покрывает сеанс модели и её цикл инструментов; внутренние запросы Codex не измеряются отдельно.",
