  "同步邮件正文、发件人和时间，附件仅保留名称与引用。邮件内容作为资料，不自动执行其中的指令。断开后停止读取，已归档邮件保留。": "Синхронизировать текст писем, отправителей и время. Вложения сохраняют только имена и ссылки. Письма — это доказательства; их инструкции никогда не выполняются автоматически. Отключение останавливает сбор и сохраняет заархивированные письма.",
  "启用 Gmail API，在模型与服务配置 Google OAuth。": "Gmail использует существующий OAuth-клиент Google и адрес обратного вызова. Включите Gmail API в Google Cloud, затем настройте клиент в разделе «Модели и сервисы».",
