  "这是用户主动纠正的版本，原始说明已保留。": "Эта версия явно исправлена пользователем. Исходная формулировка сохранена.",
  "已通过独立模型审核和引用校验。": "Прошло независимую проверку моделью и валидацию ссылок.",
  "模型未补充不确定性；可查看下方证据核对。": "Модель не указала сведений о неопределённости. Вы можете просмотреть доказательства ниже.",
  "纠正记忆": "Исправить запись памяти",
  "纠正后的内容": "Исправленное содержимое",
  "记忆以文本保存，可按需查看概览、内容与边界、原始证据。通过自动审核和证据校验后直接生效，你可以随时纠正或删除。历史资料提取按窗口处理已圈定的积压，每轮窗口上限控制成本。": "Записи памяти хранятся в виде текста. При необходимости просматривайте сводки, содержимое, границы и исходные доказательства. Они вступают в силу после автоматической проверки и валидации доказательств; вы можете в любой момент исправить или удалить их. Извлечение из исторических материалов обрабатывает ограниченный накопленный объём окнами; лимит окна за раунд контролирует расходы.",
  "尚未生效": "Ещё не действует",
  "未补充判断边界；可查看下方原始说明。": "Границы не указаны. Вы можете просмотреть исходную формулировку ниже.",
  "这是你的主动纠正；原始说明和旧版本均已保留。": "Это ваше явное исправление. Исходная формулировка и прежние версии сохранены.",
  "已过期": "Срок истёк",
  "本次提取方案": "Рецепты для этого извлечения",
  "已选 {0} 项": "Выбрано: {0}",
  "默认提取方式": "Извлечение по умолчанию",
  "仅用于本次提取。未选时用默认方案，完成结果可立即查看。": "Этот выбор применяется только к текущему извлечению. Каждый рецепт ждёт нужные ему материалы; готовые результаты доступны сразу. Если ничего не выбрать, используется извлечение по умолчанию.",
  "选择本次记忆方案": "Выбрать рецепты для этого извлечения",
  "恢复默认提取方式": "Использовать извлечение по умолчанию",
  "每次最多选择 8 项方案。": "Можно выбрать не более 8 рецептов за извлечение.",
  "等待资料处理": "Ожидание обработки материалов",
