  "已就绪方案继续处理。可查看已保存的记忆。": "Готовые рецепты продолжили обработку. Остальные рецепты ждут нужные материалы; сохранённые записи памяти уже доступны.",
  "各方案进度": "Прогресс по рецептам",
  "已完成 {0} 批": "Завершено партий: {0}",
  "所需资料：{0}": "Требуемый материал: {0}",
  "查看来源与处理": "Просмотреть источник и обработку",
  "暂停等待与后续批次": "Приостановить ожидающие входные данные и оставшиеся партии",
  "取消未完成方案": "Отменить незавершённые рецепты",
  "重新检查未完成方案": "Повторно проверить незавершённые рецепты",
  "重试会复用仍有效的提取结果；结果不可用或资料、设置变化时，可能重新提取。历史用量会保留。": "Повторные попытки используют действительные результаты извлечения. Если результаты недоступны или материалы либо настройки изменились, извлечение может выполниться заново. Прошлое использование сохраняется.",
  "所需资料仍在处理中，就绪后会自动继续。": "Требуемый материал ещё обрабатывается. Рецепт продолжится автоматически, когда он будет готов.",
  "所需资料处理失败，查看来源并修复后重新检查。": "Обработка требуемого материала не удалась. Проверьте источник, исправьте обработку и повторите проверку.",
  "所需资料不可用，查看来源与处理状态。": "Требуемый материал недоступен. Проверьте его источник и статус обработки.",
  "新产物不在本次选择的证据范围内，重新发起提取。": "Новый результат выходит за рамки доказательств, выбранных для этого запроса. Запустите новое извлечение.",
  "本次选择的方案已不可用，重新选择方案并发起提取。": "Выбранный рецепт больше недоступен. Выберите рецепты и запустите новое извлечение.",
  "来源授权已撤销，未完成的方案已停止。": "Авторизация источника отозвана. Незавершённые рецепты остановлены.",
  " · {0} 项已停止": " · {0} остановлено",
  "整体处理：": "Общая обработка: ",
  "未启用": "Не включено",
  "原始转写未校正。分人与整理结果单独生成。": "Исходная расшифровка сохранена без исправлений. Разделение говорящих и обработка диалога дают отдельные результаты.",
  "展开原始转写（未校正）": "Показать исходную расшифровку (без исправлений)",
