  "自动重试已停，失败 {0}/{1} 次。可手动重试。": "Автоматические повторные попытки извлечения памяти материала остановлены после {0}/{1} неудач. Проверьте конфигурацию и повторите вручную.",
  "校正此段文字": "Исправить этот фрагмент",
  "仅保存人工校正，不调用模型；原件和原始转写保留。": "Сохраняется только ручное исправление, без вызова модели; исходный файл и расшифровка сохраняются.",
  "保存校正": "Сохранить исправление",
  "纠正此段": "Исправить этот фрагмент",
  "仅从这条资料提取记忆": "Извлечь память только из этой записи",
  "仅从这份正式资料提取记忆": "Извлечь память только из этого опубликованного материала",
  "此资料无法单独提取记忆。查看处理状态。": "Этот опубликованный материал пока не готов к отдельному извлечению памяти. Проверьте его источник и статус обработки.",
  "查看正式资料并提取记忆": "Открыть опубликованный материал для извлечения памяти",
  "此来源的原始记录需通过正式资料提取记忆。": "Память из исходных записей этого источника извлекается через опубликованный материал.",
  "查看正式资料": "Просмотреть опубликованные материалы",
  "所选正式资料已变化或暂不可提取，重新打开当前版本。": "Выбранный опубликованный материал изменился или пока не готов к извлечению. Откройте его текущую версию заново.",
  "所选资料无效，重新打开原始记录。": "Выбранная запись недействительна. Откройте исходную запись заново.",
  "问答读取原图尚未开启。在中央感知设置中允许查询模型按需读取原图，再重新提问。": "Доступ к исходным изображениям для запросов выключен. Разрешите модели запросов читать изображения по требованию в настройках центрального восприятия, затем задайте вопрос снова.",
