  "OCR 暂不可用": "OCR недоступно",
  "中央文字识别模型尚未安装，截图已保留。": "Центральная модель OCR не установлена. Снимок экрана сохранён.",
  "文字识别受阻，截图保留。查看处理状态。": "Центральное распознавание текста заблокировано. Проверьте конфигурацию центрального восприятия и статус обработки. Снимок экрана сохранён.",
  "截图已保存，文字识别任务正在排队或处理。": "Снимок экрана сохранён. Распознавание текста в очереди или обрабатывается.",
  "文字识别已完成，下方显示这条记录保留的全文。": "Распознавание текста завершено. Полный сохранённый текст показан ниже.",
  "文字识别失败，截图已保留。": "Распознавание текста не удалось. Снимок экрана сохранён.",
  "日期使用浏览器时区。刷新可查看识别进度。": "Даты показаны в текущем часовом поясе браузера. Здесь отображаются записи, синхронизированные с центральным узлом; обновите страницу, чтобы увидеть последний статус и результаты распознавания текста.",
  "当前处理尚未结束，稍后再试。": "Текущий вызов обработки ещё не завершён. Повторите попытку позже.",
  "当前调用尚在等待结束；此时不能重试。": "Ожидание завершения текущего вызова. Повтор пока недоступен.",
  "处理已取消，后续结果不再保存。原件和已存成果保留。": "Этот запуск обработки отменён. Дальнейшие результаты не сохранятся; оригиналы и ранее сохранённые результаты остаются.",
