  "客户端需填可访问的中央地址。二维码只提供连接授权。": "Эта страница выдаёт авторизацию подключения. Сначала установите клиент Mac или Android, затем введите адрес центрального узла, до которого он может достучаться. QR-приглашение не создаёт публичный адрес или туннель.",
