  "检查对应模块即可。例如 Chat 或 Memory。": "Например, проверьте «Chat Q&A» для вопросов и «Извлечение памяти» для извлечения памяти. Нет необходимости создавать новый профиль или менять каждый модуль. Настраивайте расширенные параметры и периодичность автоматической обработки по мере необходимости.",
