  "启用周期洞察": "Включить периодические инсайты",
  "填写服务商和地址后加载模型目录。": "Сначала выберите провайдера и введите его URL. Затем загрузится каталог доступных моделей.",
  "先配置模型服务地址和默认模型。": "Сначала настройте URL сервиса и модель в Настройки → Модели и сервисы → Подключение модели (Provider). Пока не настроено, каталог моделей недоступен.",
  "配置 Google OAuth 客户端和回调地址，重启中央。": "Подготовьте клиент Google OAuth и адрес обратного вызова в Настройки → Модели и сервисы → Источники и внешние приложения, затем перезапустите центральный узел.",
