  "尚未安装": "Не установлено",
  "到「设置 → 模型与服务 → 来源与外部应用」开启 MCP，设置独立读令牌后重启。写入须另行启用，并设置允许的信源。": "MCP не включён. В Настройки → Модели и сервисы → Источники и внешние приложения включите MCP, настройте отдельный токен чтения и перезапустите. Запись также требует явного включения и разрешённых источников.",
  "设备屏幕来源": "Источник «экран устройства»",
