  "所需处理器版本当前不可用，核对当前插件与来源处理。": "Требуемая версия обработчика сейчас недоступна. Проверьте текущий плагин и настройки обработки источника.",
  "提取文本": "Извлечённый текст",
  "填写关注方向。结论以已读取资料为依据。": "Опишите в поле «Фокус», что хотите просмотреть; отчёт строится на фактически прочитанных материалах.",
  "填写地址后选择资源，不自动调用外部写入工具。": "Введите URL сервиса и выберите ресурсы. Внешние инструменты записи не вызываются автоматически.",
