  "下载中": "Скачивание",
  "在 Mac 的「来源」中连接 Coding Agent 并选择范围。": "Установите клиент Mac и подключите его к центральному узлу. В клиенте откройте Источники → Подключить Coding Agent, выберите локально доступный Claude Code, Codex или Kimi и область захвата, затем запустите синхронизацию. На этой странице показан статус синхронизации; захват управляется нативным клиентом.",
  "先核对模型连接和模块，再返回原任务。": "Сначала сохраните или проверьте подключение модели, затем проверьте модуль, используемый этой задачей. Вернитесь к исходной задаче и продолжайте доступными элементами управления.",
  "在中央授权厂商，再选择历史范围并启用同步。": "Сначала авторизуйте учётную запись провайдера на центральном узле, подтвердите необходимые разрешения чтения, затем выберите исторический диапазон и включите синхронизацию. Документы и календари Feishu имеют отдельные настройки авторизации.",
  "想分析正文时，在可访问原件的客户端保存快照。": "Чтобы проанализировать текст, сохраните снимок из клиента, который может читать оригинал.",
