  "模型目录不可读。核对连接，或填写模型 ID。": "Каталог моделей сейчас недоступен. Проверьте URL сервиса, учётные данные и поддержку каталога или введите ID модели вручную.",
  "设备应用使用可在资料库查看。": "Здесь показана фоновая работа Mote: понимание материалов, импорт, упорядочивание памяти и генерация инсайтов. Использование приложений на телефоне и компьютере — в Библиотека → Активность приложений.",
