  "历史结果保留，查看当前资料版本。失效输入不能直接重试。": "Прошлые результаты сохранены; просмотрите текущую версию материала. Недействительный ввод нельзя повторить напрямую.",
  "历史结果保留。失效输入需查看当前版本。": "Прошлые результаты сохранены; просмотрите текущую версию материала. Недействительный ввод нельзя повторить напрямую.",
