  "页面字段证据": "Доказательства полей страницы",
  "应用采集选项无效": "Недопустимые параметры захвата приложений",
  "每行使用 包名=采集选项": "Используйте «имя_пакета=параметры» в каждой строке",
  "规则必须匹配所选应用的当前安装版本": "Правила должны соответствовать текущей установленной версии выбранного приложения",
  "应用选项（每行 包名=采集选项）": "Параметры приложений (имя_пакета=параметры в каждой строке)",
  "使用本机 OCR 补充结构化内容": "Дополнять структурированный контент локальным OCR",
  "应用时长": "Длительность использования приложений",
  "结构化内容": "Структурированный контент",
  "此应用未选择结构化内容，字段规则不会运行": "Для этого приложения не выбран структурированный контент, поэтому правила полей не будут выполняться",
  "当前版本未配置字段规则；截图仍按独立选择执行": "Для этой версии не настроены правила полей. Скриншоты выполняются по отдельной настройке.",
  "本机 OCR 补充：{0}": "Дополнение локальным OCR: {0}",
  "应用活动只含前台应用和采样时长。": "Эта запись содержит только активное приложение и выборочную длительность. Скриншоты и структурированный контент сохраняются по отдельным настройкам приложения. Из-за пропусков выборки длительность не отражает полную историю использования.",
  "这条记录仅包含应用活动": "Эта запись содержит только активность приложений",
  "应用活动 · 应用与时长记录": "Активность приложений · Запись о приложении и длительности",
  "应用活动 · 本次采样 {0}": "Активность приложений · Этот замер: {0}",
  "记录时长": "Длительность записи",
  "保存截图": "Сохранять скриншоты",
  "结构化解析": "Извлекать структурированный контент",
  "扩展目录：{0}；扩展 ID：{1}": "Каталог расширения: {0}; ID расширения: {1}",
  "截图和临时 OCR 需录屏权限。时长采样无需授权。": "Для сохранения скриншотов или временного локального OCR требуется это разрешение. Для записи только длительности — нет.",
  "截图和结构化按应用分别设置。结构化失败不影响截图。字段取自实际观察范围。": "Скриншоты и структурированный контент выбираются для каждого приложения независимо. Ошибка извлечения не меняет выбор скриншотов. Поля отражают только фактически наблюдаемое.",
  "使用本机临时 OCR 补充结构化内容": "Использовать временный локальный OCR для дополнения структурированного контента",
  "关闭截图保存后，临时像素识别完即释放，图片不保存或上传。": "Если сохранение скриншотов отключено, временные пиксели освобождаются после распознавания. Изображения не сохраняются и не загружаются.",
  "Chrome 页面采集": "Сбор страниц Chrome",
  "允许采集的站点来源（每行一个完整来源地址）": "Разрешённые источники сайтов (по одному полному origin-адресу на строку)",
  "用精确 Bundle ID 分别设置时长、截图和结构化。全关时跳过该应用。画面中的应用都获准截图才保存，时长单独记录。身份或浏览器范围不明时跳过截图。设置只用于后续采样，旧队列沿用入队策略。": "Указывайте точные Bundle ID и выбирайте длительность, скриншоты и структурированный контент отдельно. Если все три выключены, записи для приложения не создаются. Для скриншотов каждое видимое приложение должно их разрешать; при неизвестной идентичности или неподтверждённой области браузера скриншоты пропускаются, а выбранная длительность всё равно записывается. Изменения действуют на будущие замеры; записи в очереди сохраняют правила на момент постановки.",
  "已设为仅记录时长。截图和结构化可单独设置。": "Добавлено только с записью длительности. Выберите скриншоты и структурированный контент отдельно в правиле, затем сохраните, чтобы применить.",
