  "账号绑定已保存，当前登录和读取权限待核验。重新检测中央运行环境，结合授权结果和同步步骤核对。": "Сохранённая привязка аккаунта не подтверждает действительный вход или права чтения. «Проверить снова» проверяет среду центрального узла; права аккаунта подтверждайте по результатам авторизации и шагам синхронизации.",
  "页面未采集。添加允许的 Chrome 站点。时长仍按设置记录。": "Структурированный контент не захвачен: сначала настройте разрешённые сайты Chrome; длительность приложений записывается по вашему выбору",
  "页面未采集。连接 Chrome 扩展。时长仍按设置记录。": "Структурированный контент не захвачен: расширение Mote для Chrome не подключено; длительность приложений записывается по вашему выбору",
  "页面未采集。检查 Chrome 窗口、站点和遮挡。时长照常记录。": "Структурированный контент не захвачен: проверки окна Chrome, разрешения сайта или видимости не пройдены; длительность приложений записывается по вашему выбору",
  "切换语言会重新加载页面，先保存未提交的修改。继续？": "Смена языка перезагрузит страницу. Сначала сохраните несохранённые изменения. Продолжить?",
  "无法保存语言偏好，检查浏览器存储。": "Не удалось сохранить языковые настройки. Проверьте хранилище браузера.",
  "切换语言会重新加载界面，先保存未提交的设置。继续？": "Смена языка перезагрузит окно. Сначала сохраните несохранённые настройки. Продолжить?",
