  "无法访问所选目录时，在系统设置中核对权限。": "Включайте только если выбранная папка недоступна. Статус проверяйте в Системных настройках.",
  "授权状态会自动更新，可随时关闭此浮条。": "Статус разрешений обновляется автоматически. Эту панель можно закрыть в любой момент.",
