  "只展示主线签发的固定制品。安装后仍须单独授权；安装不会切换 Memory 方案或开始扫描历史。": "Показаны только зафиксированные артефакты, подписанные основной линией. Установка не означает авторизацию, смену плана Memory или сканирование истории.",
  "仅列主线签发制品。安装后须另行授权或切换方案。": "Показаны только зафиксированные артефакты, подписанные основной линией. Установка не означает авторизацию, смену плана Memory или сканирование истории.",
