  "可挂到已有账号绑定": "Можно привязать к существующей привязке аккаунта",
  "中央连接器": "Центральный коннектор",
  "授权后，范围内明确的日历写入可自动执行；消息发送仍需逐条确认。更新和取消只作用于 Mote 创建的原事件；完成仅记录在 Mote。不会邀请参与人或扩大目标范围。": "После авторизации однозначные записи календаря в пределах области могут выполняться автоматически; отправка сообщений по-прежнему требует подтверждения каждого сообщения. Обновление и отмена затрагивают только исходные события, созданные Mote; завершение фиксируется только в Mote. Участники не приглашаются, целевая область не расширяется.",
  "先连接设备日历或启用官方连接器，再另行授权。": "Сначала подключите календарь на устройстве или установите, проверьте и включите в центре плагинов официальный коннектор, объявляющий действие. Установка или обновление сами по себе никогда не дают права на выполнение.",
  "能力或范围已变。刷新并重新确认。": "Возможность действия или область изменились. Обновите страницу, затем снова сохраните и подтвердите новую область.",
  "暂无已检查并启用的行动能力插件。": "Пока нет проверенных и включённых плагинов возможностей действий.",
  "暂无已连接的可写日历或中央连接器。": "Нет подключённого календаря с правом записи или центрального коннектора.",
  "选择执行位置": "Выбрать место выполнения",
  "行动能力插件": "Плагин возможностей действий",
  "我允许此插件按以上资料范围，在所选中央连接器中发送消息。": "Разрешаю этому плагину отправлять сообщения через выбранный центральный коннектор в указанной выше области источников.",
  "允许此插件按以上资料范围，通过所选中央连接器创建日程、更新或取消原事件，并在 Mote 标记完成。": "Разрешаю этому плагину создавать события, обновлять или отменять исходные события через выбранный центральный коннектор и отмечать завершение в Mote в рамках выбранных источников.",
