  "结束并入库": "End and archive",
  "确认已告知在场者并获得同意。本机仅记住一次，后续不再询问。取消不会录音。": "Confirm that everyone present has been told and agrees. This confirmation is remembered once on this device; later meeting recordings do not ask again. Cancel does not start recording.",
  "同时录制麦克风和系统音频。结束后上传至你的中央并转写。": "This meeting will record the microphone and system audio together, then upload to your Central for transcription when you end it.",
  "这场会议录音已经结束。": "This meeting recording has already ended.",
  "麦克风": "Microphone",
  "麦克风不可用": "Microphone is unavailable",
  "麦克风与系统音频 · 由你结束": "Microphone and system audio · you end it",
  "麦克风与系统音频同时录制。两项权限齐全才开始，缺项时不会只录麦克风。首次须告知在场者，本机记住一次。录音结束后进入中央文件转写，与飞书妙记、钉钉闪记和记录页的语音附件分开。": "The microphone and system audio are captured together. If either permission is missing, recording does not start and Mote never silently records only the microphone. First tell everyone present; that confirmation is remembered once on this device. When you end it, the audio enters Central's existing file transcription and is not merged with audio from the recording page or Feishu/DingTalk recordings.",
  "麦克风与系统音频已允许": "Microphone and system audio allowed",
  "麦克风与系统音频权限": "Microphone and system-audio permissions",
