  "将删除 {0} 个日志文件，共 {1}。": "Будет удалено {0} файлов журналов общим объёмом {1}.",
  "确认清理": "Подтвердить очистку",
  "详细过程单独保存，可能含个人内容。开启后最多记录 24 小时。关闭即停止新增，已有内容按保留规则清理。": "Подробные записи хранятся отдельно и могут содержать личные данные. Запись прекращается не позднее чем через 24 часа или сразу при отключении; сохранённые данные удаляются по правилам хранения.",
  "助理功能": "Ассистент",
