  "正文提取": "Извлечение текста",
  "最近观察时间。提取、理解、索引和打开原件分别确认。": "Последнее наблюдение источника не означает, что устройство сейчас в сети. Извлечение текста, семантическая обработка, векторный индекс и доступ к оригиналу подтверждаются отдельно.",
  "快照原件未保留。仍可按当前权限查看提取正文。": "Оригинал снимка не сохранён. Извлечённый текст доступен с учётом текущего охвата и прав на чтение.",
  "提取和摘要先于全文语义理解。": "Извлечение содержимого или создание сводки не означает завершения семантического анализа всего файла.",
  "向量索引尚未完整就绪；可用正文仍可通过文本检索查找。": "Векторный индекс ещё не полностью готов. Доступный текст по-прежнему можно найти текстовым поиском.",
  "问文件": "Спросить об этом файле",
  "基于此文件拟可编辑草稿，写明目标和范围。确认后开始。": "Подготовь редактируемый рабочий черновик на основе этого файла. Укажи цель и охват материалов и дождись моего подтверждения перед началом.",
  "用于事项": "Использовать для дела",
  "用于事项会先准备可编辑草稿，点击开始后才执行。": "Сначала будет подготовлен редактируемый черновик. Работа начнётся только после нажатия «Начать».",
  "只更改此来源的保存方式。已有文件以实际状态为准。": "При сохранении отправляется только выбранный режим хранения. Другие настройки источника не меняются. Фактические возможности существующих файлов указаны в их состоянии.",
