  "历史预算比例": "Доля бюджета истории",
  "历史预算比例需要在 0 到 1 之间。": "Доля бюджета истории должна быть от 0 до 1.",
  "对话设置已保存。": "Настройки диалога сохранены.",
  "已接收": "Принято",
  "指定模型窗口": "Указать окно модели",
  "指定模型窗口需要填写正整数。": "Указанное окно модели должно быть положительным целым числом.",
  "排队等待回答": "В очереди на ответ",
  "只保存比例和窗口偏好。中央按模型窗口和请求预算计算。": "Сервер вычисляет цель истории из текущего окна модели и полного бюджета запроса. Эта форма сохраняет только доли и параметры окна; браузер их не оценивает.",
  "模型窗口": "Окно модели",
  "窗口大小（tokens）": "Размер окна (токены)",
  "能力未知时用保守窗口。历史目标取比例与预算的较小值。": "Если нет достоверных сведений о возможностях, используется консервативное окно. Цель истории — меньшее из доли и бюджета запроса; сервер вычисляет её при каждом запросе.",
  "设置尚未读取完成，稍后重试。": "Настройки ещё не загружены. Повторите попытку чуть позже.",
