  "按已关联的记忆身份浏览；同名人物分别保留。": "Просмотр по связанным идентификаторам памяти. Одноимённые люди остаются отдельными.",
  "本页暂无已关联的人物。可继续浏览记忆或主题。": "На этой странице нет связанных людей. Можно продолжить просмотр воспоминаний или тем.",
