  "初次认识仍只处理你选择的资料。": "Первое знакомство по-прежнему обрабатывает только выбранные вами материалы.",
  "保存方式可在来源的「连接与范围」修改。": "Способ хранения берётся из настроек источника; чтобы изменить его, откройте «Подключение и область» этого источника.",
