  "摘要、语义分组、复核、Memory 与 Ask 继续使用各自所选模型。": "Сводки, смысловая группировка, проверка, Memory и Ask по-прежнему используют выбранные для них модели.",
  "保守消重仅影响派生稿；原文始终可对照和导出。": "Консервативное удаление дублей затрагивает только производную расшифровку; оригинал всегда доступен для сравнения и экспорта.",
  "使用 CAM++": "Использовать CAM++",
