  "截至 {0}": "По {0}",
  "首次同步建立基线，随后跟踪新增和已归档资料修订。": "Первая синхронизация создаёт исходную точку. Последующие получают новые материалы и отслеживают изменения уже собранных материалов.",
  "可安全推进的解析会自动保存；关键缺口需要确认。": "Результаты, с которыми можно безопасно продолжить, сохраняются автоматически; существенные пробелы требуют подтверждения.",
  "解析确认状态未知。核对预览。": "В результате анализа не указано, нужно ли подтверждение. Проверьте предварительный просмотр.",
  "解析未说明继续处理的依据，核对预览。": "В результате анализа не объяснено, на каком основании можно продолжить. Проверьте предварительный просмотр.",
