  "飞书会话需要单独的消息读取授权；不会开启发送权限。": "Для переписки Feishu нужно отдельно разрешить чтение сообщений. Разрешение на отправку не включается.",
  "在系统浏览器打开授权页面": "Открыть страницу авторизации в системном браузере",
