  "可选内容列表未完整返回，只能选择当前已列出的内容。": "Список доступного содержимого неполон. Можно выбрать только элементы, отображаемые сейчас.",
  "保存后读取已选来源，保留已有归档。": "Сохранение области включает чтение выбранных источников. Невыбранное содержимое не собирается, существующие архивы сохраняются.",
