  "仅接入新增内容": "Только новое содержимое",
  "只读归档已选择的内容，按原始身份保留版本。": "Архивирование выбранного содержимого только для чтения с сохранением версий под исходными идентификаторами.",
  "先配置并启用插件，再连接账号和选择读取范围。": "Установка не предоставляет доступ. Настройте и включите плагин в центре плагинов, затем подключите учётную запись и выберите содержимое для чтения.",
  "停止读取飞书会话并暂停所选会话。保留归档和此飞书账号的其他连接。": "Остановить чтение переписки Feishu и приостановить выбранные чаты. Архивы и другие подключения учётной записи Feishu сохранятся.",
  "删除这条原始记录及不再被引用的影像；仍有效的记忆保留，原文将无法回看或引用。": "Удалить эту исходную запись и изображения, на которые больше нет ссылок. Действительные воспоминания сохранятся; оригинал больше нельзя будет просмотреть или процитировать.",
  "删除中央文件原件和解析正文；仍有效的记忆保留，原文将无法回看或引用。来源设备上的原文件保留。": "Удалить исходный файл и разобранный текст в Central. Действительные воспоминания сохранятся; оригинал больше нельзя будет просмотреть или процитировать. Исходный файл на устройстве-источнике останется.",
  "原件已释放，无法回看或引用。有效记忆仍可用。": "Оригинал освобождён и больше недоступен для просмотра или цитирования. Это воспоминание по-прежнему можно использовать в пределах его области действия.",
  "JSON 备份含本机采集记录、关联图片和上传状态。恢复时沿用该上传状态。来源文件与会议录音单独备份。": "Резервные копии JSON содержат локально собранные записи, статус загрузки и связанные изображения. При восстановлении статус загрузки сохраняется. Исходные файлы и записи встреч нужно сохранять отдельно.",
  "清理本机副本": "Удалить локальную копию",
  "本机副本已清理": "Локальная копия удалена",
  "本机原件不在此设备，连接原中央后可按当前权限读取。": "Оригинала нет на этом устройстве. Подключитесь к исходному Central, чтобы прочитать его с текущими правами доступа.",
  "原中央与当前连接不一致，未发送读取请求。": "Исходный Central не соответствует текущему подключению. Запрос на чтение не отправлен.",
